-- 7. The two archive announcements, as drafts like the news (no reliable dates/season).
insert into public.articles(title,slug,body,summary,category,status,is_headline)
select v.title,v.slug,v.body,'Imported archive story; publication date and season require review.','announcement','draft',false
from (values
('3 - 6  November , The magnificent organization in Antalya','icc-source-announcement-1','An amazing atmosphere awaits our teams at the İnternational Championships of Companies that will take place at the Limak Arcadia Golf&Sport Resort.

Don''t be late to get involved in this great organization !!!

Archive source: https://arsiv.cclcup.com/internationalcorporatecup/duyuru-1-3---6--november---the-magnific.html'),
('2 - 5 November , The magnificent organization in Antalya','icc-source-announcement-2','An amazing atmosphere awaits our teams at the İnternational Championships of Companies that will take place at the Limak Arcadia Golf&Sport Resort.

Don''t be late to get involved in this great organization !!!

Archive source: https://arsiv.cclcup.com/internationalcorporatecup/duyuru-2-2---5-november---the-magnifice.html')
) v(title,slug,body)
where exists(select 1 from public.seasons where id in (45,46,47))
  and not exists(select 1 from public.articles a where a.slug=v.slug);

do $verify$ begin
 if exists(select 1 from pg_trigger where tgrelid='public.match_squads'::regclass and not tgisinternal and tgenabled<>'O') then
   raise exception 'match_squads trigger not restored';
 end if;
 if exists(select 1 from public.seasons where id in (45,46,47)) then
   if (select count(*) from public.media_assets a join public.matches m on m.id=a.match_id
       where m.season_id in (45,46,47) and a.kind='highlight') < 52 then raise exception 'highlights missing'; end if;
   if (select count(*) from public.matches where season_id in (45,46,47) and stream_url is not null) < 56 then
     raise exception 'match videos missing'; end if;
   if exists(select 1 from public.match_squads s join public.matches m on m.id=s.match_id
       where m.season_id in (45,46,47) group by s.match_id,s.team_id
       having count(*) filter(where s.is_goalkeeper)<>1) then raise exception 'each imported lineup needs one goalkeeper'; end if;
 end if;
end $verify$;
